package com.masterclass.inventory.entity;
import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;
@Entity @Table(name="sale_details", indexes={@Index(name="ix_sale_details_sale",columnList="sale_id"),@Index(name="ix_sale_details_product",columnList="product_id")}) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class SaleDetail { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="sale_id",nullable=false,foreignKey=@ForeignKey(name="fk_details_sales")) private Sale sale; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false,foreignKey=@ForeignKey(name="fk_details_products")) private Product product; @Column(nullable=false) private int quantity; @Column(name="unit_price",nullable=false,precision=12,scale=2) private BigDecimal unitPrice; @Column(nullable=false,precision=12,scale=2) private BigDecimal subtotal; }
